/);
const cleaned = lines.map(line => line.replace(/,\s*$/, '')).join('
');
return { ...$json, text: cleaned };

const md = $json.output || '';

function escapeHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function inline(text) {
  text = escapeHtml(text);
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/(^|[^*])\*([^*]+?)\*($|[^*])/g, '$1<em>$2</em>$3');
  text = text.replace(/`([^`]+)`/g, '<code style="background:#f1f5f9;padding:1px 4px;border-radius:3px;">$1</code>');
  text = text.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" style="color:#2563eb;">$1</a>');
  return text;
}

const lines = md.split(/\r?\n/);
let html = '';
let inList = false;
let listType = null;
let inTable = false;
let tableRows = [];

function closeList() {
  if (inList) {
    html += listType === 'ol' ? '</ol>' : '</ul>';
    inList = false;
    listType = null;
  }
}

function flushTable() {
  if (!tableRows.length) return;
  html += '<table style="width:100%;border-collapse:collapse;margin:12px 0;font-size:13px;">';
  tableRows.forEach((row, i) => {
    const cells = row.split('|').map(c => c.trim()).filter((c, idx, arr) => !(idx === 0 && c === '') && !(idx === arr.length - 1 && c === ''));
    if (cells.every(c => /^:?-+:?$/.test(c))) return;
    const tag = i === 0 ? 'th' : 'td';
    html += '<tr>' + cells.map(c => `<${tag} style="border:1px solid #e2e8f0;padding:6px 8px;text-align:left;${tag === 'th' ? 'background:#f8fafc;font-weight:600;' : ''}">${inline(c)}</${tag}>`).join('') + '</tr>';
  });
  html += '</table>';
  tableRows = [];
  inTable = false;
}

for (const raw of lines) {
  const line = raw.trim();

  if (line.startsWith('|')) {
    inTable = true;
    tableRows.push(line);
    continue;
  } else if (inTable) {
    flushTable();
  }

  if (/^#{1,6}\s/.test(line)) {
    closeList();
    const level = Math.min(line.match(/^#+/)[0].length, 4);
    const text = line.replace(/^#+\s*/, '');
    const sizes = { 1: '22px', 2: '19px', 3: '16px', 4: '14px' };
    html += `<h${level} style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#0f172a;margin:18px 0 8px;font-size:${sizes[level]};">${inline(text)}</h${level}>`;
    continue;
  }

  if (/^(-{3,}|\*{3,})$/.test(line)) {
    closeList();
    html += '<hr style="border:none;border-top:1px solid #e2e8f0;margin:16px 0;">';
    continue;
  }

  if (/^[-*]\s+/.test(line)) {
    if (!inList || listType !== 'ul') {
      closeList();
      html += '<ul style="margin:8px 0;padding-left:20px;">';
      inList = true;
      listType = 'ul';
    }
    html += `<li style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:13px;color:#334155;line-height:1.5;margin-bottom:4px;">${inline(line.replace(/^[-*]\s+/, ''))}</li>`;
    continue;
  }

  if (/^\d+\.\s+/.test(line)) {
    if (!inList || listType !== 'ol') {
      closeList();
      html += '<ol style="margin:8px 0;padding-left:20px;">';
      inList = true;
      listType = 'ol';
    }
    html += `<li style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:13px;color:#334155;line-height:1.5;margin-bottom:4px;">${inline(line.replace(/^\d+\.\s+/, ''))}</li>`;
    continue;
  }

  closeList();
  if (line === '') continue;
  html += `<p style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:13px;color:#334155;line-height:1.6;margin:0 0 10px;">${inline(line)}</p>`;
}
closeList();
flushTable();

const reportDate = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

const wrapped = `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portfolio Research Report</title></head><body style="margin:0;padding:0;background:#0f172a;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#0f172a;"><tr><td align="center" style="padding:32px 10px;"><table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="max-width:600px;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 20px 25px -5px rgba(15,23,42,.3);"><tr><td style="padding:0 24px 6px;background-color:#1e2937;background:linear-gradient(135deg,#0f172a 0%,#1e2937 100%);"><table width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td style="padding:24px 0 18px;text-align:center;"><div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:11px;font-weight:600;color:#e2a87d;letter-spacing:1px;margin-bottom:6px;">STOCK AGENT</div><h1 style="margin:0 0 8px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:22px;line-height:1.2;font-weight:700;color:#fff;">Portfolio Research Report</h1><p style="margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:13px;color:#cbd5e1;">${reportDate}</p></td></tr></table></td></tr><tr><td style="padding:20px 24px;">${html}</td></tr><tr><td style="padding:14px 24px;background:#0f172a;color:#94a3b8;"><div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:10px;line-height:1.5;">Automated research generated by your Stock Agent n8n workflow. Not financial advice — verify all figures before acting.</div></td></tr></table></td></tr></table></body></html>`;

return { ...$json, emailHtml: wrapped };
